PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS Dates(dateRep TEXT NOT NULL UNIQUE ON CONFLICT ROLLBACK, day INTEGER NOT NULL, month INTEGER NOT NULL, year INTEGER NOT NULL, PRIMARY KEY(dateRep) ON CONFLICT ROLLBACK);
CREATE TABLE IF NOT EXISTS Countries(geoId TEXT NOT NULL UNIQUE ON CONFLICT ROLLBACK, countriesAndTerritories TEXT NOT NULL UNIQUE ON CONFLICT ROLLBACK, countryterritoryCode TEXT NOT NULL UNIQUE ON CONFLICT ROLLBACK, continentExp TEXT NOT NULL, PRIMARY KEY(geoId) ON CONFLICT ROLLBACK);
CREATE TABLE IF NOT EXISTS CovidData(dateRep TEXT NOT NULL, geoId TEXT NOT NULL, cases INTEGER, deaths INTEGER, PRIMARY KEY(dateRep,geoId) ON CONFLICT ROLLBACK, FOREIGN KEY(dateRep) REFERENCES Dates(dateRep), FOREIGN KEY(geoId) REFERENCES Countries(geoId));
CREATE TABLE IF NOT EXISTS CountryPopulationByYear(geoId TEXT NOT NULL UNIQUE ON CONFLICT ROLLBACK, popData2020 INTEGER NOT NULL, PRIMARY KEY(geoId) ON CONFLICT ROLLBACK, FOREIGN KEY(geoId) REFERENCES Countries(geoId));
COMMIT;